PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS chapters(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,households INTEGER CHECK(households IS NULL OR households>=0),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS chapter_access(chapter_id TEXT NOT NULL REFERENCES chapters(id),email TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'chapter' CHECK(role IN ('chapter','editor')),PRIMARY KEY(chapter_id,email));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',scope TEXT NOT NULL DEFAULT 'all',status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',due_at TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn','archived')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS task_assignments(task_id TEXT NOT NULL REFERENCES tasks(id),chapter_id TEXT NOT NULL REFERENCES chapters(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','in_progress','completed')),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(task_id,chapter_id));
CREATE TABLE IF NOT EXISTS submissions(id TEXT PRIMARY KEY,chapter_id TEXT NOT NULL REFERENCES chapters(id),kind TEXT NOT NULL CHECK(kind IN ('report','activity','situation','feedback')),title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('draft','submitted','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS member_counts(chapter_id TEXT NOT NULL REFERENCES chapters(id),period TEXT NOT NULL,members_total INTEGER NOT NULL CHECK(members_total>=0),members_new INTEGER NOT NULL DEFAULT 0 CHECK(members_new>=0),members_left INTEGER NOT NULL DEFAULT 0 CHECK(members_left>=0),updated_by TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(chapter_id,period));
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_submissions_chapter ON submissions(chapter_id,created_at);
CREATE INDEX IF NOT EXISTS idx_assignments_chapter ON task_assignments(chapter_id,status);

